/* Buildless and dependency-free. Works on static hosting and directly from files. */
(() => {
  'use strict';
  const {skills,questions:Q,missions,weeks,revision,stats,curriculum:C}=window.ISLAND;
  const KEY='nuonuo-island-v1';
  const fresh=()=>({version:1,contentRevision:revision,completed:{},legacyCompleted:{},drafts:{},sessions:{},reviewed:{},mistakes:{},journal:[],days:[]});
  let state=fresh(),storageOK=true,session=null,week=1;
  const $=(s)=>document.querySelector(s);
  const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  try {const raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(x?.version===1&&x.completed&&x.drafts&&Array.isArray(x.journal))state=migrateState(x);}}catch{storageOK=false;}

  function migrateState(x){
    const next={...fresh(),...x};
    if(x.contentRevision!==revision){
      next.legacyCompleted={...(x.legacyCompleted||{}),...x.completed};
      next.completed={};next.sessions={};next.contentRevision=revision;
      next.upgradeNotice=Object.keys(x.completed).length>0||Object.keys(x.drafts).length>0||Object.keys(x.reviewed||{}).length>0||Object.keys(x.sessions||{}).length>0||x.journal.length>0;
      for(const [id,r] of Object.entries(x.reviewed||{}))if(Q[id]&&r.kind==='revised')next.mistakes[id]={date:r.date,count:1};
    }
    return next;
  }
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;showStorageWarning();}};
  const touch=()=>{if(!state.days.includes(today()))state.days.push(today());};
  const icon=(name,size=21)=>{
    const paths={leaf:'<path d="M12 21v-9m0 4C4 17 3 7 4 5c8-1 10 5 8 11Zm0-4C11 5 17 3 21 4c0 6-4 9-9 8Z"/>',spark:'<path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8L12 2Z"/><path d="M20 2v4m-2-2h4"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 6 6M7.5 10.5h6m-3-3v6"/>',arrows:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',pencil:'<path d="m4 16-1 5 5-1L20 8l-4-4L4 16Zm10-10 4 4M3 22h18"/>',home:'<path d="m3 10 9-7 9 7v11H3V10Z"/><path d="M9 21v-8h6v8"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-2-7-1-10 1Zm0 0v15"/>',heart:'<path d="M20 4c-3-2-6 0-8 3C10 4 7 2 4 4c-5 4 0 10 8 17 8-7 13-13 8-17Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',flag:'<path d="M5 22V3c5-4 9 4 15 0v11c-6 4-10-4-15 0"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v5h16v-5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 .5-1 1-1 2m0 3h.01"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z"/>'};
    return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.leaf}</svg>`;
  };
  const art=()=>`<svg viewBox="0 0 440 310" fill="none" aria-hidden="true"><ellipse cx="223" cy="257" rx="160" ry="15" fill="#cdd8b7" opacity=".45"/><path d="M58 215c10-45 56-38 71-66 24-42 51-30 78-45 41-23 44-4 82-12 40-8 38 29 61 51 25 23 49 62 20 81-54 35-268 37-312-9Z" fill="#d4dfbc"/><path d="M76 225c44-46 95 22 132-17s-8-57 30-77 75 6 98 27" stroke="#fffdf3" stroke-width="14" stroke-linecap="round"/><path d="M76 225c44-46 95 22 132-17s-8-57 30-77 75 6 98 27" stroke="#95a57b" stroke-width="1.4" stroke-dasharray="3 8"/><g transform="translate(78 112)"><path d="M-6 41 29 3l34 38" fill="#f2c59c" stroke="#8b9c72" stroke-width="1.5"/><path d="M0 41h57v42H0z" fill="#fffbee" stroke="#8b9c72" stroke-width="1.5"/><path d="M22 83V54h16v29M7 49h10v11H7zM44 49h7v11h-7z" stroke="#8b9c72" stroke-width="1.5"/><path d="M28 2v-30m0 0 28 8-28 8" stroke="#7c8f61" stroke-width="1.5" fill="#f3db83"/></g><g transform="translate(267 172) rotate(-11)"><path d="M0 5C20-7 40-4 55 5v61C33 54 18 55 0 64Z" fill="#fffdf3" stroke="#879c6e" stroke-width="1.5"/><path d="M55 5c20-12 38-8 55 0v59c-19-9-35-10-55 2Z" fill="#f5f2d8" stroke="#879c6e" stroke-width="1.5"/><path d="M13 20h26M13 29h28M14 38h19M70 18h24M70 28h24M70 38h18" stroke="#bec5a2" stroke-width="2" stroke-linecap="round"/><path d="M55 5v62" stroke="#879c6e"/></g><g transform="translate(206 136)"><path d="M-21 35c-4-17-3-35 3-42C-7-18 15-17 22-3c7 12 5 26 1 38" fill="#f5e7b9" stroke="#819567" stroke-width="1.8"/><path d="M-6-13c-18-10-11-26-11-26 19 1 22 18 11 26ZM-5-13C-7-33 11-40 18-37c-1 16-10 23-23 24Z" fill="#8fa66a" stroke="#6d8750" stroke-width="1.5"/><path d="M-23 34c0 11 47 11 47 0" stroke="#819567" stroke-width="1.8"/><circle cx="-8" cy="9" r="2" fill="#546d44"/><circle cx="10" cy="9" r="2" fill="#546d44"/><path d="M-3 18q5 5 9 0" stroke="#546d44" stroke-width="1.5" stroke-linecap="round"/><circle cx="-14" cy="15" r="4" fill="#eac7a0"/><circle cx="16" cy="15" r="4" fill="#eac7a0"/></g><path d="M331 94V42m0 0 33 10-33 10" stroke="#82966d" stroke-width="1.8" fill="#eebd94"/><g stroke="#819967" stroke-width="1.6"><path d="M61 98v-15m-7 8h14M366 117v-12m-6 6h12M168 67v-10m-5 5h10"/></g><g fill="#9bb275"><circle cx="52" cy="194" r="3"/><circle cx="394" cy="191" r="3"/><circle cx="264" cy="70" r="3"/></g><g transform="translate(120 244)"><path d="M0 0v-24m0 15c-12-1-12-10-12-10 12-1 12 10 12 10Zm0-7c0-12 12-14 12-14 2 11-12 14-12 14Z" stroke="#8c9f6c" stroke-width="1.6" fill="#c0ce9b"/></g><rect x="302" y="74" width="62" height="23" rx="11.5" fill="#fff9e9" stroke="#d5dfbf"/><text x="333" y="89" text-anchor="middle" fill="#758a5b" font-size="9" font-family="sans-serif">发现 · 思考</text><rect x="57" y="239" width="62" height="23" rx="11.5" fill="#fff9e9" stroke="#d5dfbf"/><text x="88" y="254" text-anchor="middle" fill="#758a5b" font-size="9" font-family="sans-serif">表达 · 生长</text></svg>`;
  const page=document.body.dataset.page;
  const names={home:'探险首页',plan:'四周任务地图',train:'语文闯关',journal:'观察手记',library:'题库书架',parents:'家长陪伴指南',curriculum:'全册课程目录'};
  const nav=[['home','index.html','home','探险首页','01'],['plan','plan.html','map','任务地图','02'],['library','library.html','search','题库书架','03'],['curriculum','curriculum.html','book','全册课程','04'],['journal','journal.html','book','观察手记','05'],['parents','parents.html','heart','家长指南','06']];
  function shell(){
    $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="index.html" aria-label="返回探险首页"><span class="brand-mark">${icon('leaf',29)}</span><span class="brand-text"><b>语文探险岛</b><small>NUONUO'S ISLAND</small></span></a><div class="nav-label">我的探险手册</div><nav class="nav-links" aria-label="主导航">${nav.map(([id,href,ic,label,n])=>`<a class="nav-link ${page===id||(page==='train'&&id==='plan')?'active':''}" href="${href}" aria-label="${label}" title="${label}" ${page===id?'aria-current="page"':''}>${icon(ic,19)}<span>${label}</span><small class="nav-index">${n}</small></a>`).join('')}</nav><div class="sidebar-bottom"><div class="leaf-note">${icon('leaf',17)}每天，长出一点新本领</div><div class="sidebar-note">四年级 · 语文成长计划<br><span class="tiny-label">观察 / 思考 / 表达</span></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><span>诺诺的学习小天地</span><span>/</span><span>${names[page]}</span></div><div class="top-right"><span class="save-note"><i class="dot"></i>进度保存在此浏览器</span><span class="avatar" aria-label="诺诺">诺</span></div></header><main id="main" tabindex="-1"></main><footer class="footer"><span>小小的发现，也值得认真记录。</span><span>原创练习 · 四年级语文 · 每周四次，自由安排</span></footer></div></div><div id="toast" class="toast hidden" role="status"></div>`;
    showStorageWarning();
    if(state.upgradeNotice){$('.topbar').insertAdjacentHTML('afterend','<div class="upgrade-banner">题库已加入四上全册训练。旧草稿、观察手记和旧版完成记录已保留；四周任务地图使用80个不同关卡。<button id="dismiss-upgrade" class="button small secondary">知道了</button></div>');$('#dismiss-upgrade').onclick=()=>{state.upgradeNotice=false;save();$('.upgrade-banner').remove();};}
  }
  function showStorageWarning(){if(!storageOK&&!$('#storage-warning'))$('.topbar')?.insertAdjacentHTML('afterend','<div id="storage-warning" class="error-banner" role="alert">当前浏览器无法保存本地进度。请及时导出备份；关闭页面后，本次记录可能丢失。</div>');}
  function intro(kicker,title,desc,extra=''){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
  function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),3200);}
  const completed=()=>missions.filter(m=>state.completed[m.id]).length;
  const nextMission=()=>missions.find(m=>!state.completed[m.id])||missions[0];
  function home(){
    const next=nextMission();
    $('#main').innerHTML=intro('HELLO, LITTLE EXPLORER','诺诺，欢迎回到探险岛','今天也一起，发现藏在文字里的小秘密。',`<span class="date-chip">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>`)+`<section class="hero" aria-label="今日推荐任务"><div class="hero-copy"><span class="pill">${icon('leaf',12)} 一次小探险 · 约 ${next.minutes} 分钟</span><h2>把好奇心装进口袋，<br>让<em>语文本领</em>悄悄长大。</h2><p>今天的推荐：第 ${next.week} 周 · ${next.title}<br>读一读、找一找、说一说。每次只练好一个小本领。</p><div class="hero-action"><a class="button" href="train.html?mission=${next.id}">${Object.keys(state.sessions).includes(next.id)?'继续今日探险':'开始今日探险'} ${icon('arrow',17)}</a><a class="text-link" href="plan.html">查看任务地图 ${icon('arrow',14)}</a></div></div><div class="hero-art">${art()}<span class="art-caption">EVERY LITTLE DISCOVERY COUNTS</span></div></section><section class="stats" aria-label="成长记录">${[[icon('flag'),'已完成任务',completed(),' / 16'],[icon('spark'),'练习过的小关卡',Object.keys(state.reviewed).length,' 关'],[icon('book'),'留下的观察手记',state.journal.length,' 篇'],[icon('leaf'),'有练习的日子',state.days.length,' 天']].map(([ic,label,n,unit])=>`<div class="stat"><div class="stat-icon">${ic}</div><div><strong>${n}<span>${unit}</span></strong><p>${label}</p></div></div>`).join('')}</section><div class="section-head"><div><div class="section-kicker">EXPLORE YOUR WAY</div><h2>六个小岛，六种新本领</h2><p>${stats.core} 个专项活动 + ${stats.reserved} 个迁移挑战 · 覆盖 ${stats.units} 单元 · ${stats.lessons} 篇文本 · 全册字词表</p></div><a class="text-link" href="library.html">浏览全部题库 ${icon('arrow',15)}</a></div><div class="card-grid">${skills.map((s,i)=>`<a href="train.html?skill=${s.id}" class="skill-card"><div class="card-top"><span class="icon-tile ${s.color}">${icon(s.icon,27)}</span><span class="card-number">ISLAND 0${i+1}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="card-bottom"><span>每次 ${s.batchSize} 关 / 题库 ${s.ids.length} 关</span><b>换组练习 ${icon('arrow',15)}</b></div></a>`).join('')}</div><div class="footer-strip">${icon('map',27)}<div><b>跟着学校进度，打开全册课程</b><p>八单元逐课练习，字词、积累、口语与习作都有入口。</p></div><a class="button secondary" href="curriculum.html">全册课程 →</a></div><div class="footer-strip">${icon('book',27)}<div><b>文字之外，还有真实世界里的发现</b><p>选一盆植物，连续看看它。记下变化，也记下你的好奇。</p></div><a class="text-link" href="journal.html">写一则手记 ${icon('arrow',16)}</a></div>`;
  }
  function plan(){
    const requested=Number(new URLSearchParams(location.search).get('week'));
    if(requested>=1&&requested<=4)week=requested;else week=nextMission().week;
    renderPlan();
  }
  function renderPlan(){const w=weeks[week-1],list=missions.filter(m=>m.week===week),count=list.filter(m=>state.completed[m.id]).length;
    $('#main').innerHTML=intro('YOUR FOUR-WEEK ADVENTURE','四周任务地图','每周四次、每次5关，共80个不重复的主线活动。专项题库可随时补充练习。')+`<div class="week-tabs" role="group" aria-label="选择训练周次">${weeks.map((_,i)=>`<button class="week-tab ${week===i+1?'active':''}" data-week="${i+1}" aria-pressed="${week===i+1}">第 ${i+1} 周</button>`).join('')}</div><section class="week-header"><div><div class="tiny-label">WEEK 0${week}</div><h2>${w.name}</h2><p>${w.goal}</p><p>观察支线：${w.journal}</p></div><span class="week-counter">${count}<small style="font-size:13px"> / 4</small></span></section><div class="mission-grid">${list.map(m=>`<article class="mission"><div class="mission-top"><div class="mission-day">任务<strong>${String(m.day).padStart(2,'0')}</strong></div><div><h3>${m.title}</h3><p>${m.desc}</p></div></div><div class="mission-tags">${[...new Set(m.questions.map(id=>skills.find(s=>s.id===Q[id].skill).tag))].map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="mission-end"><span>${state.completed[m.id]?'✓ 已完成，可再次练习':state.sessions[m.id]?'已有进度，可以继续':`${m.questions.length} 个小关卡 · 约 ${m.minutes} 分钟`}</span><a class="button small ${state.completed[m.id]?'secondary':''}" href="train.html?mission=${m.id}">${state.completed[m.id]?'再练一次':state.sessions[m.id]?'继续任务':'进入任务'} ${icon('arrow',14)}</a></div></article>`).join('')}</div><div class="footer-strip">${icon('leaf',26)}<div><b>本周别忘了：观察真实世界</b><p>${w.journal} 手记与闯关任务分别记录。</p></div><a class="text-link" href="journal.html">打开手记 ${icon('arrow',15)}</a></div><p class="note">完成阅读题需要选对答案；简答和写作按自查清单完成，系统不会自动判断文字质量。第四周前3次任务包含前面未使用的新材料。</p>`;
    document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{week=Number(b.dataset.week);history.replaceState(null,'',`plan.html?week=${week}`);renderPlan();});
  }
  function practicePool(skill,reviewOnly=false){
    return Object.values(Q).filter(q=>(!skill||q.skill===skill.id)&&(!q.reserved||reviewOnly)&&(!reviewOnly||state.mistakes[q.id]));
  }
  function pickPractice(pool,limit){
    const age=id=>{const previous=state.reviewed[id]||state.mistakes[id];return previous?Math.floor((Date.now()-new Date(previous.date+'T00:00:00').getTime())/86400000):Infinity;};
    const priority=q=>state.mistakes[q.id]&&age(q.id)>=2?0:!state.reviewed[q.id]?1:state.mistakes[q.id]?2:age(q.id)>=7?3:4;
    const ranked=pool.map(q=>({q,p:priority(q),random:Math.random()})).sort((a,b)=>a.p-b.p||a.random-b.random);
    const result=[];let writing=0,recall=0;
    for(const {q} of ranked){if(q.type==='writing'&&writing>=1)continue;if(q.type==='recall'&&recall>=1&&pool.some(x=>x.type!=='recall'))continue;result.push(q.id);if(q.type==='writing')writing++;if(q.type==='recall')recall++;if(result.length===limit)break;}
    return result;
  }
  function startTrain(){
    const params=new URLSearchParams(location.search),m=missions.find(m=>m.id===params.get('mission'));
    const one=Q[params.get('question')],single=one&&!one.reserved?one:null;
    const lesson=C.lessons.find(l=>l.id===params.get('lesson')),unit=C.units.find(u=>String(u.id)===params.get('unit'));
    const coursePool=lesson?lesson.questions:unit?unit.questions:null;
    const sk=skills.find(s=>s.id===(single?.skill||params.get('skill'))),reviewOnly=params.get('practice')==='review';
    const practice=reviewOnly||params.get('practice')==='all';
    if(!m&&!sk&&!single&&!practice&&!coursePool){$('#main').innerHTML=intro('FIND YOUR NEXT STOP','先选一个探险任务','从任务地图开始，或到题库书架挑一个小练习。')+'<a class="button" href="library.html">打开题库书架</a>';return;}
    const key=m?.id||(lesson?'lesson-'+lesson.id:unit?'unit-'+unit.id:single?'question-'+single.id:sk?'skill-'+sk.id+(reviewOnly?'-review':''):reviewOnly?'practice-review':'practice-all');
    let saved=state.sessions[key];
    let ids=m?.questions||(lesson?lesson.questions:single?[single.id]:saved?.ids?.filter(id=>Q[id]&&(!sk||Q[id].skill===sk.id)&&(!Q[id].reserved||reviewOnly)&&(!coursePool||coursePool.includes(id))));
    if(!ids?.length)ids=pickPractice(coursePool?coursePool.map(id=>Q[id]):practicePool(sk,reviewOnly),sk?.batchSize||5);
    if(!ids.length){$('#main').innerHTML=intro('A LITTLE REST IS GOOD',reviewOnly?'暂时没有待复练的题':'这组题暂时为空',reviewOnly?'答题时需要重试或提示的题，会出现在这里。你也可以选几道新题。':'回到题库书架看看其他活动。')+'<a class="button" href="library.html">返回题库书架</a>';return;}
    session={key,mission:m,skill:sk,title:m?.title||lesson?.title||(unit?'第'+unit.id+'单元 · '+unit.title:null)||single?.title||(reviewOnly?'错题复练':sk?.name||'跨岛混合练习'),ids,index:saved?.index||0,results:saved?.results||[],wrong:saved?.wrong||false,selected:null,evidence:null,order:[],hint:saved?.hint||false,solved:false,feedback:null,recallIndex:0,recallStage:0,recallRetry:false};
    if(session.index>=session.ids.length){session.index=0;session.results=[];}
    if(session.results[session.index]){session.solved=true;const q=Q[session.ids[session.index]];session.feedback={kind:'success',title:'这小关已经完成，可以继续啦',text:q.why||'你的文字或默写自查已经保存，继续下一小关吧。'};}
    persistSession();renderTrain();
  }
  const persistSession=()=>{state.sessions[session.key]={ids:session.ids,index:session.index,results:session.results,wrong:session.wrong,hint:session.hint};save();};
  const draftFor=id=>state.drafts[id]||{text:'',checks:[]};
  function diagram(){return `<div class="diagram-set" aria-label="三个洞穴图纸示意">${[0,1,2].map(i=>`<div class="diagram-box"><b>${'ABC'[i]}</b><svg viewBox="0 0 140 130" role="img" aria-label="${['平整洞口、直通道、宽底部','有土堆、直通道、宽底部','平整洞口、横通道'][i]}"><path d="M8 22h124" stroke="#82916d" stroke-width="1.5"/>${i===1?'<path d="M20 22q13-23 28 0M88 22q15-20 27 0" stroke="#b99374" fill="#e9d5ba"/>':''}${i===2?'<path d="M59 22v30h56v20H45V22" fill="#fffdf2" stroke="#7a9169" stroke-width="2"/>':'<path d="M59 22v62c-35 8-30 38 11 38s47-30 11-38V22" fill="#fffdf2" stroke="#7a9169" stroke-width="2"/>'}</svg></div>`).join('')}</div>`;}
  function renderTrain(){
    const q=Q[session.ids[session.index]],sk=skills.find(s=>s.id===q.skill),d=draftFor(q.id),pct=session.index/session.ids.length*100;
    $('#main').innerHTML=intro(session.mission?`WEEK 0${session.mission.week} / MISSION ${String(session.mission.day).padStart(2,'0')}`:'FREE EXPLORATION',esc(session.title),session.mission?session.mission.desc:'每次一小组，新题优先；完成后再次进入，可换一组。')+`<div class="training-layout"><div><div class="training-top"><a class="text-link" href="${session.mission?'plan.html?week='+session.mission.week:'library.html'}">← 返回${session.mission?'任务地图':'题库书架'}</a><span>小关卡 ${session.index+1} / ${session.ids.length} · 随时可以休息</span></div><div class="progress-track" role="progressbar" aria-label="本次练习进度" aria-valuenow="${session.index}" aria-valuemin="0" aria-valuemax="${session.ids.length}"><div class="progress-fill" style="width:${pct}%"></div></div><article class="exercise"><span class="pill">${icon(sk.icon,13)} ${sk.tag} · ${['','基础','进阶','挑战'][q.level]}</span><h2>${q.title}</h2>${q.type==='evidence'?'<p class="passage-caption">阅读材料 · 点选一句作为证据</p>':''}${q.course&&q.category==='reading'?'<p class="note">以下为自编导读材料；精读时请结合课本原文。</p>':''}${q.passage?`<div class="passage">${q.passage.map((line,i)=>q.type==='evidence'?`<button class="passage-line selectable ${session.evidence===i?'selected':''}" data-evidence="${i}" aria-pressed="${session.evidence===i}" ${session.solved?'disabled':''}><small>${i+1}</small>${line}</button>`:`<div class="passage-line">${line}</div>`).join('')}</div>`:''}${q.course?`<p class="note course-source">第 ${q.unit} 单元 · ${esc(q.sourceTitle)}${q.page?` · 教材第 ${q.page} 页起`:''}</p>`:''}${q.diagram?diagram():''}<p class="prompt">${q.prompt}</p>${questionBody(q,d)}${q.tip?`<div class="${session.hint?'hint':'hidden'}" id="hint-box">小提示：${q.tip}</div>`:''}<div id="feedback" aria-live="polite">${feedbackHTML()}</div><div class="actions">${session.solved?`<button class="button" id="next-question">${session.index===session.ids.length-1?'完成这次探险':'下一小关'} ${icon('arrow',16)}</button>`:q.type==='recall'?'':`<button class="button" id="submit-answer">${q.type==='writing'?'完成自查，继续':'检查我的发现'} ${icon('check',16)}</button>`}${q.tip&&!session.solved?`<button class="hint-button" id="show-hint">${icon('help',15)} 给我一点提示</button>`:''}</div></article></div><aside class="side-coach">${icon('leaf',30)}<h3>小芽的探险提醒</h3><ol><li>先看题目要找什么。</li><li>回到原文，找出依据。</li><li>用自己的话说清楚。</li></ol><div class="coach-divider"></div><p>不急着答对。能讲清“为什么”，就是新的收获。</p><div class="coach-divider"></div><a class="text-link" href="journal.html">去记录一个真实发现 ${icon('arrow',13)}</a></aside></div>`;
    bindQuestion(q);
  }
  function questionBody(q,d){
    if(q.type==='choice'||q.type==='evidence')return `<div class="options" role="group" aria-label="选择答案">${q.options.map((o,i)=>`<button class="option ${session.selected===i?'selected':''}" data-option="${i}" aria-pressed="${session.selected===i}" ${session.solved?'disabled':''}><span class="option-letter">${'ABC'[i]}</span><span>${o}</span></button>`).join('')}</div>${q.type==='evidence'?'<p class="note">还要在上方短文中点选一句证据，再检查答案。</p>':''}`;
    if(q.type==='writing')return `<label class="field"><span>我的想法（自动保存草稿）</span><textarea id="writing-answer" placeholder="先说给自己听，再把意思写清楚……" ${session.solved?'disabled':''}>${esc(d.text)}</textarea></label><div class="word-count" id="word-count">已输入 ${Array.from(d.text.trim()).length} 字符</div><div class="review-label">这是自查练习：勾选表示你已检查，系统不会自动批改文字。</div><div class="checklist"><div class="checklist-title">写完后，一项一项检查</div>${q.checks.map((c,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${d.checks.includes(i)?'checked':''} ${session.solved?'disabled':''}><span>${c}</span></label>`).join('')}</div><details class="sample"><summary>需要时再打开：参考思路</summary><p>${q.sample}</p><p class="note">参考只提供一种思路。请用自己的话表达，也可以请家人一起对照清单讨论。</p></details>`;
    if(q.type==='order')return `<div class="order-list">${q.items.map((s,i)=>`<button class="order-item ${session.order.includes(i)?'chosen':''}" data-order="${i}" ${session.order.includes(i)||session.solved?'disabled':''}><span class="option-letter">${'ABC'[i]}</span>${s}</button>`).join('')}</div><div class="order-output" aria-live="polite">${session.order.length?session.order.map((i,n)=>`<div class="order-picked">${n+1}. ${q.items[i]}</div>`).join(''):'按事情发生的顺序，点击上方卡片。'}</div>${!session.solved?'<button class="hint-button" id="reset-order">重新排序</button>':''}`;
    if(q.type==='recall')return recallHTML(q);
    return '';
  }
  function recallHTML(q){
    const c=q.cards[session.recallIndex];if(!c)return '';
    const read=q.mode==='read',recite=q.mode==='recite';
    const hidden=!read&&(session.recallStage===1||(q.delayed&&session.recallStage===0));
    const pronunciation=read&&session.recallStage!==2?'先自己试着读':c.pinyin;
    return `<div class="recall-steps"><span>${read?'看字试读':recite?'读懂词句':'读懂字词'}</span><span>${read?'翻卡对音':recite?'遮住背诵':'遮住，纸上写'}</span><span>核对自查</span><span>隔天再测</span></div><div class="recall-card"><span class="tiny-label">${read?'认读':recite?'积累':'记忆'}卡 ${session.recallIndex+1} / ${q.cards.length}</span><div class="pinyin">${esc(pronunciation)}</div><div class="recall-word ${recite?'recitation-text':''}" aria-label="${hidden?'内容已遮住':esc(c.word)}">${hidden?'· · ·':esc(c.word)}</div>${hidden?`<p>${recite?'请背诵或在纸上默写，完成后翻卡核对。':'请在纸上写下来。写完再翻卡核对。'}</p>`:`<p>${esc(c.sentence)}</p><p>${esc(c.hint)}</p>`}${session.solved?'':read&&session.recallStage!==2?'<button class="button" id="recall-reveal">我读好了，核对读音</button>':session.recallStage===0?(q.delayed?'<button class="button" id="recall-reveal">写好了，翻卡核对</button>':`<button class="button" id="recall-hide">${recite?'遮住，试着背诵':'我看清了，遮住默写'}</button>`):session.recallStage===1?'<button class="button" id="recall-reveal">完成了，翻卡核对</button>':`<p>${read?'请对照拼音重新读一遍，留意本课中的读音。':'请逐项核对，不确定的地方请翻课本或请家人帮助。'}</p><button class="button" id="recall-correct">${session.recallRetry?'这次核对正确了':read?'我核对过，读对了':recite?'背诵 / 默写自查完成':'我核对过，写对了'}</button><button class="button secondary" id="recall-retry">还需再练一次</button>`}</div><p class="note">${read?'认读由你自己核对；需要练字时，请选写字或词语默写。':recite?'背诵、默写需要自己或家人核对，完成不等于自动评分。':'默写由你自己核对。点击按钮不能代替纸上书写。'}</p>`;
  }
  function feedbackHTML(){if(!session.feedback)return '';return `<div class="feedback ${session.feedback.kind==='retry'?'retry':''}"><b>${esc(session.feedback.title)}</b><p>${esc(session.feedback.text)}</p></div>`;}
  function bindQuestion(q){
    document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{session.selected=Number(b.dataset.option);session.feedback=null;renderTrain();$(`[data-option="${session.selected}"]`)?.focus();});
    document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{session.evidence=Number(b.dataset.evidence);session.feedback=null;renderTrain();$(`[data-evidence="${session.evidence}"]`)?.focus();});
    document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{session.order.push(Number(b.dataset.order));session.feedback=null;renderTrain();(document.querySelector('[data-order]:not(:disabled)')||$('#submit-answer'))?.focus();});
    $('#reset-order')?.addEventListener('click',()=>{session.order=[];session.feedback=null;renderTrain();});
    $('#show-hint')?.addEventListener('click',()=>{session.hint=true;persistSession();$('#hint-box').classList.remove('hidden');});
    $('#writing-answer')?.addEventListener('input',e=>{const d=draftFor(q.id);state.drafts[q.id]={text:e.target.value,checks:d.checks};$('#word-count').textContent=`已输入 ${Array.from(e.target.value.trim()).length} 字符`;save();});
    document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{const d=draftFor(q.id),n=Number(b.dataset.check);state.drafts[q.id]={text:d.text,checks:b.checked?[...new Set([...d.checks,n])]:d.checks.filter(i=>i!==n)};save();});
    $('#submit-answer')?.addEventListener('click',()=>submit(q));
    $('#next-question')?.addEventListener('click',nextQuestion);
    $('#recall-hide')?.addEventListener('click',()=>{session.recallStage=1;renderTrain();});
    $('#recall-reveal')?.addEventListener('click',()=>{session.recallStage=2;renderTrain();});
    $('#recall-retry')?.addEventListener('click',()=>{session.recallStage=1;session.recallRetry=true;renderTrain();toast('把易错处看清楚，再遮住写一次。');});
    $('#recall-correct')?.addEventListener('click',()=>{touch();if(session.recallIndex<q.cards.length-1){session.recallIndex++;session.recallStage=0;session.recallRetry=false;renderTrain();}else{markSolved(q,'self');session.feedback={kind:'success',title:q.mode==='read'?'认读自查完成':q.mode==='recite'?'积累自查完成':'纸上默写，自查完成',text:q.mode==='read'?'隔两天再看字试读，并放回课文词句中练习。':q.mode==='recite'?'隔两天再背诵或默写，核对词句与字形。':'隔两天或一周再遮住写，看看能不能独立想起来。'};renderTrain();}});
  }
  function submit(q){
    if(session.solved)return;
    if(q.type==='writing'){
      const d=draftFor(q.id);if(d.text.trim().length<8){toast('先写下你的想法，再完成自查。');return;}
      if(!q.checks.every((_,i)=>d.checks.includes(i))){toast('请逐项检查清单；需要修改的地方，先补充完整。');return;}
      markSolved(q,'self');session.feedback={kind:'success',title:'想法已保存，自查完成',text:'这关记录的是你的练习和自查。可以请家人听一听：意思讲清楚了吗？有没有具体依据？'};
    }else{
      if((q.type==='choice'||q.type==='evidence')&&session.selected===null){toast('先选一个你认为合适的答案。');return;}
      if(q.type==='evidence'&&session.evidence===null){toast('还差一步：点选短文中能证明答案的那句话。');return;}
      if(q.type==='order'&&session.order.length!==q.items.length){toast('请把所有卡片按顺序加入故事。');return;}
      const correct=q.type==='order'?session.order.every((x,i)=>x===q.answer[i]):session.selected===q.answer&&(q.type!=='evidence'||q.evidence.includes(session.evidence));
      if(correct){markSolved(q,session.wrong?'revised':session.hint?'guided':'first');session.feedback={kind:'success',title:session.wrong?'重新检查，找到依据了！':session.hint?'借助提示，找到依据了！':'发现正确，理由也要带上！',text:q.why};}
      else{session.wrong=true;state.mistakes[q.id]={date:today(),count:(state.mistakes[q.id]?.count||0)+1};touch();persistSession();session.feedback={kind:'retry',title:'再检查一个小细节',text:q.type==='evidence'&&session.selected===q.answer?'答案的方向对了，再找最直接支持它的那一句。':(q.tip||'回到原文，看看每一个条件是否都符合。')};}
    }
    renderTrain();
    (session.solved?$('#next-question'):$('#submit-answer'))?.focus();
  }
  function markSolved(q,kind){session.solved=true;touch();state.reviewed[q.id]={date:today(),kind};if(kind==='first')delete state.mistakes[q.id];if(kind==='guided')state.mistakes[q.id]={date:today(),count:state.mistakes[q.id]?.count||1};session.results[session.index]={id:q.id,kind};persistSession();}
  function nextQuestion(){
    if(!session.solved)return;
    session.index++;session.selected=null;session.evidence=null;session.order=[];session.hint=false;session.feedback=null;session.solved=false;session.wrong=false;session.recallIndex=0;session.recallStage=0;session.recallRetry=false;
    if(session.index>=session.ids.length){if(session.mission)state.completed[session.mission.id]={date:today()};delete state.sessions[session.key];save();showSummary();}
    else{persistSession();renderTrain();}
    $('#main').scrollIntoView({behavior:'smooth',block:'start'});
  }
  function showSummary(){const auto=session.results.filter(r=>r.kind!=='self'),self=session.results.filter(r=>r.kind==='self'),next=nextMission();
    $('#main').innerHTML=intro('ONE LITTLE STEP FORWARD','今天，又长出一点新本领','认真检查和独立修改，都是探险的一部分。')+`<div class="panel summary"><div class="celebrate">${icon('leaf',45)}</div><h2>“${esc(session.title)}”已完成</h2><p>把今天最有用的方法，说给家人听听吧。</p><div class="summary-stats"><div><b>${auto.length}</b><span>答案核对完成</span></div><div><b>${self.length}</b><span>文字 / 默写自查</span></div><div><b>${auto.filter(r=>r.kind==='revised').length}</b><span>重新检查后发现</span></div></div><p class="note">这些数字只记录练习过程，不代表标准化能力评分。</p><div class="actions" style="justify-content:center"><a class="button" href="${session.mission?'plan.html?week='+session.mission.week:'library.html'}">返回${session.mission?'任务地图':'题库书架'} ${icon('arrow',16)}</a>${!session.mission?`<a class="button secondary" href="train.html?${session.key.includes('review')?'practice=review':session.skill?'skill='+session.skill.id:'practice=all'}">再来一组新题</a>`:''}<a class="button secondary" href="journal.html">写一则观察手记</a></div><p class="note" style="margin-top:25px">${completed()===16?'四周80关全部走过啦！题库书架还有更多专项活动，也可以挑一段旧作再修改。':`下次可以继续：${next.title}。今天的休息时间，也很重要。`}</p></div>`;
  }
  function journal(){
    $('#main').innerHTML=intro('MY LITTLE FIELD NOTES','观察手记','选同一个对象，隔一段时间再看。记录事实，也给猜想留一个位置。')+`<div class="journal-grid"><section class="panel"><h2>今天，你发现了什么？</h2><p>推荐对象：同一盆植物、几粒种子，或一片树叶。只记录真实观察到的内容。</p><form id="journal-form"><div class="form-row"><label class="field"><span>观察日期</span><input type="date" id="journal-date" value="${today()}" required></label><label class="field"><span>观察对象</span><input id="journal-object" maxlength="50" placeholder="例如：窗台上的绿豆" required></label></div><label class="field"><span>我看到的事实 · 颜色、形状、长度、数量……</span><textarea id="journal-facts" placeholder="今天和上次相比，哪里变了？哪里没有变？" required></textarea></label><label class="field"><span>我的猜想 / 问题（选填）</span><textarea id="journal-thought" style="min-height:90px" placeholder="我猜……但还需要继续观察。"></textarea></label><label class="field"><span>我的心情（选填）</span><input id="journal-mood" maxlength="100" placeholder="例如：发现新芽时，我有点惊喜。"></label><div class="actions"><button class="button" type="submit">保存这次发现 ${icon('check',16)}</button></div></form></section><section class="panel"><div class="section-head" style="margin-top:0"><div><h2>我的发现集</h2><p>${state.journal.length} 则记录 · 按观察日期排列</p></div><button class="button secondary small" id="print-journal">打印</button></div><div id="journal-entries">${entriesHTML()}</div><p class="note">每次记录后保存。需要跨设备使用时，请在家长指南中导出备份。</p></section></div>`;
    const localDraftKey='journalDraft';
    const fields=['date','object','facts','thought','mood'];
    const draft=state.drafts[localDraftKey];if(draft)fields.forEach(f=>{if(typeof draft[f]==='string')$(`#journal-${f}`).value=draft[f];});
    fields.forEach(f=>$(`#journal-${f}`).addEventListener('input',()=>{state.drafts[localDraftKey]=Object.fromEntries(fields.map(k=>[k,$(`#journal-${k}`).value]));save();}));
    $('#journal-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(fields.map(k=>[k,$(`#journal-${k}`).value.trim()]));if(!data.object||!data.facts){toast('请写下观察对象和看到的事实。');return;}state.journal.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,...data});delete state.drafts[localDraftKey];touch();save();journal();toast('这次发现已经保存。下次再来看看它的变化。');};
    $('#print-journal').onclick=()=>window.print();
    document.querySelectorAll('[data-delete-entry]').forEach(b=>b.onclick=()=>{if(window.confirm('确定删除这则观察记录吗？')){state.journal=state.journal.filter(e=>e.id!==b.dataset.deleteEntry);save();journal();toast('这则记录已删除。');}});
  }
  function entriesHTML(){if(!state.journal.length)return '<div class="empty-state">一张空白的小手记，<br>正等着你的第一个发现。</div>';return [...state.journal].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<article class="journal-entry"><div class="entry-head"><div><time>${esc(e.date)}</time><h3>${esc(e.object)}</h3></div><button class="delete-entry" data-delete-entry="${esc(e.id)}" aria-label="删除${esc(e.date)}的${esc(e.object)}记录">删除</button></div><p><b>看到的事实</b><br>${esc(e.facts)}</p>${e.thought?`<p><b>猜想 / 问题</b><br>${esc(e.thought)}</p>`:''}${e.mood?`<p><b>我的心情</b> ${esc(e.mood)}</p>`:''}</article>`).join('');}
  function library(){
    const types={choice:'选择判断',evidence:'答案与证据',writing:'简答 / 写作',order:'故事排序',recall:'认读 / 默写 / 积累'};
    const params=new URLSearchParams(location.search);
    let pageNumber=1;
    $('#main').innerHTML=intro('A BOOKSHELF OF DISCOVERIES','题库书架',`${stats.core} 个可自由选择的活动，覆盖全册课程和六类专项；另有 ${stats.reserved} 个第四周迁移挑战。`)+`<div class="library-overview"><div><strong>${stats.total}</strong><span>训练活动</span></div><div><strong>${stats.scheduled}</strong><span>主线不重复关卡</span></div><div><strong>${stats.vocabulary}</strong><span>全册词语表词语</span></div><div><strong>${Object.keys(state.mistakes).length}</strong><span>待复练的客观题</span></div></div><div class="library-actions"><a class="button" href="train.html?practice=all">${icon('spark',17)} 跨岛换组练5关</a><a class="button secondary" href="train.html?practice=review">错题复练 ${icon('arrow',16)}</a><a class="text-link" href="plan.html">按四周主线练习 →</a></div><section class="panel library-filters" aria-label="筛选题库"><label class="field"><span>专项</span><select id="filter-skill"><option value="">全部小岛</option>${skills.map(s=>`<option value="${s.id}">${s.name} · ${s.ids.length}关</option>`).join('')}</select></label><label class="field"><span>难度</span><select id="filter-level"><option value="">全部难度</option><option value="1">基础 · 找到直接信息</option><option value="2">进阶 · 解释和比较</option><option value="3">挑战 · 综合与迁移</option></select></label><label class="field"><span>题型</span><select id="filter-type"><option value="">全部题型</option>${Object.entries(types).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="field"><span>练习状态</span><select id="filter-state"><option value="">全部状态</option><option value="new">还没练过</option><option value="done">已经练过</option><option value="review">需要复练</option></select></label><label class="field"><span>单元</span><select id="filter-unit"><option value="">全册与专项</option>${C.units.map(u=>`<option value="${u.id}">第${u.id}单元 · ${u.title}</option>`).join('')}</select></label><label class="field"><span>课文</span><select id="filter-lesson"><option value="">全部课文</option>${C.lessons.map(l=>`<option value="${l.id}">${l.title}</option>`).join('')}</select></label><label class="field"><span>内容</span><select id="filter-category"><option value="">全部内容</option>${Object.entries(courseCategories).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="field search-field"><span>找一个主题或关键词</span><input id="filter-search" type="search" placeholder="例如：观察、最多、心情、顺序" maxlength="80"></label></section><div class="section-head"><div><h2 id="library-count"></h2><p>自由练习每组新题优先；故事与汉字小岛每次3关，其余小岛每次5关。</p></div><button class="button secondary small" id="reset-filters">清空筛选</button></div><div id="library-grid" class="library-grid"></div><div id="library-pagination" class="library-pagination" aria-label="题库翻页"></div><p class="note">“写过”与“答对”分别记录：简答、写作和纸上默写仍需要对照清单或由家人核对。错题复练先保留需要重试或提示的客观题，下一轮独立答对后移出待复练列表。</p>`;
    function renderItems(){
      const unit=$('#filter-unit').value,lesson=$('#filter-lesson').value,category=$('#filter-category').value;
      const skill=$('#filter-skill').value,level=$('#filter-level').value,type=$('#filter-type').value,status=$('#filter-state').value,search=$('#filter-search').value.trim().toLowerCase();
      const filtered=Object.values(Q).filter(q=>!q.reserved&&(!unit||q.unit===Number(unit))&&(!lesson||q.lesson===lesson)&&(!category||(category==='targeted'?!q.course:q.category===category))&&(!skill||q.skill===skill)&&(!level||q.level===Number(level))&&(!type||q.type===type)&&(!status||(status==='new'?!state.reviewed[q.id]:status==='done'?state.reviewed[q.id]:state.mistakes[q.id]))&&(!search||[q.title,q.prompt,q.sourceTitle||'',...(q.passage||[]),...(q.cards||[]).map(c=>c.word)].join(' ').toLowerCase().includes(search)));
      const totalPages=Math.max(1,Math.ceil(filtered.length/12));pageNumber=Math.min(pageNumber,totalPages);
      $('#library-count').textContent=`找到 ${filtered.length} 个活动`;
      $('#library-grid').innerHTML=filtered.length?filtered.slice((pageNumber-1)*12,pageNumber*12).map(q=>{const s=skills.find(s=>s.id===q.skill),summary=(q.passage?.join(' ')||q.prompt);return `<article class="library-card"><div class="card-top"><span class="tag">${s.name}</span><span class="level-badge level-${q.level}">${['','基础','进阶','挑战'][q.level]}</span></div><h3>${q.title}</h3><p>${esc(summary.slice(0,90))}${summary.length>90?'…':''}</p><div class="library-card-bottom"><span>${q.category?courseCategories[q.category]:types[q.type]}${q.unit?' · 第'+q.unit+'单元':''} · ${state.mistakes[q.id]?'待复练':state.reviewed[q.id]?'已练过':'新题'}</span><a class="text-link" href="train.html?question=${q.id}">打开这关 ${icon('arrow',14)}</a></div></article>`;}).join(''):'<div class="empty-state full-width">这个条件下暂时没有题目，试试调整筛选。</div>';
      $('#library-pagination').innerHTML=`<button class="button secondary small" id="previous-page" ${pageNumber===1?'disabled':''}>上一页</button><span>第 ${pageNumber} / ${totalPages} 页</span><button class="button secondary small" id="following-page" ${pageNumber===totalPages?'disabled':''}>下一页</button>`;
      $('#previous-page').onclick=()=>{pageNumber--;renderItems();$('#library-count').scrollIntoView({block:'start'});};
      $('#following-page').onclick=()=>{pageNumber++;renderItems();$('#library-count').scrollIntoView({block:'start'});};
    }
    for(const id of ['skill','level','type','state','unit','lesson','category'])$('#filter-'+id).onchange=()=>{pageNumber=1;renderItems();};
    $('#filter-search').oninput=()=>{pageNumber=1;renderItems();};
    $('#reset-filters').onclick=()=>{for(const id of ['skill','level','type','state','search','unit','lesson','category'])$('#filter-'+id).value='';pageNumber=1;renderItems();};
    for(const key of ['unit','lesson','category'])if(params.get(key))$('#filter-'+key).value=params.get(key);
    renderItems();
  }
  function curriculum(){
    const requested=Number(new URLSearchParams(location.search).get('unit')),active=C.units.find(u=>u.id===requested);
    const list=active?[active]:C.units;
    $('#main').innerHTML=intro('THE WHOLE BOOK, ONE STEP AT A TIME','四上全册课程','以你上传的2024版教材为准。27课拆分为35篇文本（含两篇习作例文），逐篇阅读训练；八次习作、四次口语交际及全册字词积累均可按目录进入。')+`<div class="library-overview"><div><strong>${stats.course}</strong><span>全册配套活动</span></div><div><strong>250 + 21</strong><span>生字 + 多音复习项</span></div><div><strong>250</strong><span>写字表用字</span></div><div><strong>240</strong><span>词语表词语</span></div></div><nav class="unit-tabs" aria-label="单元导航"><a href="curriculum.html" class="button ${!active?'':'secondary'} small">全册</a>${C.units.map(u=>`<a href="curriculum.html?unit=${u.id}" class="button ${active?.id===u.id?'':'secondary'} small">第${u.id}单元</a>`).join('')}</nav><p class="note">阅读题使用自编导读材料和新材料；精读、背诵请结合教材原文。完成记录表示已练习，自查项需要自己或家人核对。</p>${list.map(u=>{
      const qs=u.questions.map(id=>Q[id]),done=qs.filter(q=>state.reviewed[q.id]).length,lessons=C.lessons.filter(l=>l.unit===u.id);
      const inventory=(category)=>qs.filter(q=>q.category===category).flatMap(q=>q.cards||[]);
      return `<section class="panel course-unit" id="unit-${u.id}"><div class="section-head"><div><div class="section-kicker">UNIT 0${u.id}</div><h2>第${u.id}单元 · ${u.title}</h2><p>${u.goal}</p></div><a class="button small" href="train.html?unit=${u.id}">本单元换组练5关 →</a></div><p class="note">已练 ${done} / ${qs.length} 个活动</p><div class="progress-track"><div class="progress-fill" style="width:${done/qs.length*100}%"></div></div><div class="course-lessons">${lessons.map(l=>`<article class="course-lesson"><span class="tiny-label">教材 P.${l.page} · ${l.number.startsWith('x')?'习作例文':'第'+l.number.replace(/[ab]/g,'').replace('c','')+'课'}</span><h3>${l.title}</h3><p>线索证据 · 词义理解 · 方法表达</p><p class="note">逐篇训练 ${l.questions.filter(id=>state.reviewed[id]).length} / ${l.questions.length}</p><a class="text-link" href="train.html?lesson=${l.id}">进入3关 →</a><a class="text-link course-more" href="library.html?lesson=${l.id}">全部配套</a></article>`).join('')}</div><div class="course-links">${Object.entries(courseCategories).filter(([key])=>qs.some(q=>q.category===key)).map(([key,label])=>`<a class="tag" href="library.html?unit=${u.id}&category=${key}">${label} · ${qs.filter(q=>q.category===key).length}关</a>`).join('')}</div><details class="course-inventory"><summary>展开本单元字词清单（每项均有对应卡片）</summary>${[['recognition','识字（含多音复习）'],['handwriting','写字'],['vocabulary','词语']].map(([key,label])=>`<h3>${label} · ${inventory(key).length}项</h3><p>${inventory(key).map(c=>esc(c.word)).join(' · ')||'本单元无独立词语表条目，请练课文与积累。'}</p>`).join('')}</details><div class="course-essay"><h3>习作：${u.essay}</h3><p>每一步单独保存草稿，完成后可在家长指南回看。</p><div class="course-links">${u.essayQuestions.map((id,i)=>`<a class="button secondary small" href="train.html?question=${id}">${i+1}. ${['选材','列提纲','写初稿','修改'][i]}${state.reviewed[id]?' ✓':''}</a>`).join('')}</div></div></section>`;
    }).join('')}<section class="footer-strip"><div><b>先做全册同步，再做弱项加练</b><p>全册目录按教材安排；四周主线继续针对词语作用、原文证据、比较与表达。</p></div><a class="text-link" href="plan.html">打开四周计划 →</a></section>`;
  }
  function parents(){
    const drafts=Object.entries(state.drafts).filter(([id,d])=>Q[id]&&typeof d.text==='string'&&d.text.trim());
    $('#main').innerHTML=intro('GROW TOGETHER','陪伴，也是一种小小的魔法','每天少一点催促，多一个追问：你从哪句话发现的？')+`<div class="parent-grid"><section class="panel"><h2>为什么这样安排？</h2><p>根据已有语文试卷表现，这份计划集中训练：词语作用、原文证据、同角度比较、审题方向、字形回忆和关键情节表达。练习使用原创短文，避免只记住旧题答案。</p><ul class="info-list"><li><b>每周四次，每次15—20分钟。</b>可配合校内作业调整，不必连续四天完成。</li><li><b>先口述，再书写。</b>口头也讲不清，回到材料理解；口头清楚却写漏了，再练组织答案。</li><li><b>不把所有错误归为粗心。</b>分清题目方向、知识理解和表达组织的问题。</li><li><b>写作和默写需要人工核对。</b>清单是自查工具，完成不等于文字内容一定正确。</li></ul><div class="sample"><b>三句陪伴提示</b><p>① 题目让你找什么？<br>② 哪一句能证明？<br>③ 你的答案把意思说清楚了吗？</p></div></section><section class="panel"><h2>记录与备份</h2><p>所有任务进度、文字草稿和观察手记保存在当前设备的当前浏览器中。不会自动跨设备同步；清理浏览器数据会影响这些记录。</p><p class="note">网站不上传课本、试卷或孩子的原始作答。请只导出需要自己保存的练习记录。</p><div class="data-actions"><button class="button" id="export-data">${icon('download',17)} 导出备份</button><button class="button secondary" id="import-data">导入备份</button><input id="import-file" type="file" accept="application/json,.json" class="hidden" aria-label="选择备份文件"></div><p class="note">导入将覆盖此浏览器当前的探险记录。系统会先显示确认提示；建议先导出当前数据。</p><div class="coach-divider" style="border-top:1px solid var(--line);margin:24px 0"></div><h2>两周后，怎么看变化？</h2><p>换一段没做过的短文，让诺诺独立找证据、解释限定词、按同一角度概括。记录需要几次提醒，看看能否把旧方法用到新材料。</p><p class="note">当前有 ${completed()} 个新版任务完成、${state.journal.length} 则观察记录、${drafts.length} 段文字草稿；保留 ${Object.keys(state.legacyCompleted).length} 条旧版任务完成记录。记录用于家庭观察，不作能力排名。</p></section><section class="panel full-width"><h2>四周陪伴路线</h2><div class="table-wrap"><table><thead><tr><th>时间</th><th>主要任务</th><th>可以观察的变化</th></tr></thead><tbody>${weeks.map((w,i)=>`<tr><td class="nowrap">第 ${i+1} 周</td><td>${w.goal}</td><td>${['解释小词时，能说清它在句中的意思。','比较两件事时，能把双方放在同一个角度下。','故事里能看到具体行动和前后的变化。','在新材料上独立使用方法，而非复述旧答案。'][i]}</td></tr>`).join('')}</tbody></table></div></section><section class="panel full-width"><h2>文字草稿集</h2><p>这里保留简答和习作练习，方便一起回看、讨论和修改。</p>${drafts.length?drafts.map(([id,d])=>`<details class="sample"><summary>${Q[id].title} · ${state.reviewed[id]?'已完成自查':'草稿中'}</summary><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(d.text)}</p><a class="text-link" href="train.html?question=${id}">打开这道练习继续修改 →</a></details>`).join(''):'<div class="empty-state">完成第一段文字练习后，草稿会出现在这里。</div>'}</section></div>`;
    $('#export-data').onclick=exportData;
    $('#import-data').onclick=()=>$('#import-file').click();
    $('#import-file').onchange=importData;
  }
  function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`语文探险岛备份-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('备份已生成，请妥善保存下载文件。');}
  function normalizeBackup(x){
    if(!x||x.version!==1||!x.completed||!x.drafts||!Array.isArray(x.journal))throw new Error('这不是可识别的探险岛备份。');
    const clean=fresh(),dateRE=/^\d{4}-\d{2}-\d{2}$/;
    for(const m of missions)if(x.completed[m.id]&&dateRE.test(x.completed[m.id].date)){
      if(x.contentRevision===revision)clean.completed[m.id]={date:x.completed[m.id].date};else clean.legacyCompleted[m.id]={date:x.completed[m.id].date};
    }
    for(const m of missions){const old=x.legacyCompleted?.[m.id];if(old&&dateRE.test(old.date))clean.legacyCompleted[m.id]={date:old.date};}
    for(const id of Object.keys(Q)){const mistake=x.mistakes?.[id];if(mistake&&dateRE.test(mistake.date))clean.mistakes[id]={date:mistake.date,count:Math.max(1,Math.min(999,Number(mistake.count)||1))};}
    for(const id of Object.keys(Q)){const d=x.drafts[id];if(d&&typeof d.text==='string'&&Array.isArray(d.checks))clean.drafts[id]={text:d.text.slice(0,30000),checks:d.checks.filter(n=>Number.isInteger(n)&&n>=0&&n<10)};const r=x.reviewed?.[id];if(r&&dateRE.test(r.date)&&['self','first','revised','guided'].includes(r.kind))clean.reviewed[id]={date:r.date,kind:r.kind};}
    if(Array.isArray(x.days))clean.days=[...new Set(x.days.filter(d=>typeof d==='string'&&dateRE.test(d)))];
    if(x.journal.length>5000)throw new Error('记录数量过多，请检查备份文件。');
    for(const [i,e] of x.journal.entries()){if(!e||!dateRE.test(e.date)||typeof e.object!=='string'||typeof e.facts!=='string')throw new Error('观察记录格式不完整，未导入任何数据。');clean.journal.push({id:`import-${Date.now()}-${i}`,date:e.date,object:e.object.slice(0,50),facts:e.facts.slice(0,30000),thought:typeof e.thought==='string'?e.thought.slice(0,30000):'',mood:typeof e.mood==='string'?e.mood.slice(0,100):''});}
    // Only restore sessions from this curriculum with known, validated question lists.
    if(x.contentRevision===revision){
      const allowed=new Map([...C.lessons.map(l=>['lesson-'+l.id,l.questions]),...C.units.map(u=>['unit-'+u.id,u.questions]),...missions.map(m=>[m.id,m.questions]),...skills.flatMap(s=>[['skill-'+s.id,s.ids],['skill-'+s.id+'-review',Object.keys(Q).filter(id=>Q[id].skill===s.id)] ]),...Object.values(Q).filter(q=>!q.reserved).map(q=>['question-'+q.id,[q.id]]),['practice-all',Object.keys(Q).filter(id=>!Q[id].reserved)],['practice-review',Object.keys(Q)]]);
      for(const [key,pool] of allowed){const se=x.sessions?.[key];if(!se||!Array.isArray(se.ids)||!se.ids.length||se.ids.length>5||!se.ids.every(id=>pool.includes(id))||new Set(se.ids).size!==se.ids.length)continue;
        if(key.startsWith('day')&&JSON.stringify(se.ids)!==JSON.stringify(pool))continue;
        if(!Number.isInteger(se.index)||se.index<0||se.index>=se.ids.length||!Array.isArray(se.results))continue;
        clean.sessions[key]={ids:se.ids,index:se.index,wrong:se.wrong===true,hint:se.hint===true,results:se.results.slice(0,se.index+1).map((r,i)=>({id:se.ids[i],kind:['first','revised','self','guided'].includes(r?.kind)?r.kind:'self'}))};
      }
    }else{clean.upgradeNotice=true;for(const [id,r] of Object.entries(clean.reviewed))if(r.kind==='revised'||r.kind==='guided')clean.mistakes[id]??={date:r.date,count:1};}
    return clean;
  }
  async function importData(e){const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw new Error('备份文件超过5MB，请检查所选文件。');const clean=normalizeBackup(JSON.parse(await f.text()));if(!window.confirm(`将导入 ${Object.keys(clean.completed).length} 个已完成任务和 ${clean.journal.length} 则手记，并覆盖当前记录。是否继续？`)){e.target.value='';return;}state=clean;save();parents();toast('备份已导入，草稿和记录已恢复。');}catch(err){toast(err instanceof SyntaxError?'文件不是有效的JSON备份，当前记录未更改。':err.message);e.target.value='';}}
  const courseCategories={reading:'逐篇阅读',recognition:'识字认读',handwriting:'写字默写',vocabulary:'词语表',garden:'语文园地',method:'交流平台与初试身手',accumulation:'背诵与积累',essay:'习作四步',oral:'口语交际','unit-test':'单元新材料挑战','reading-project':'快乐读书吧',targeted:'原有弱项专项'};
  if(state.upgradeNotice)save();
  shell();
  ({home,plan,train:startTrain,journal,library,parents,curriculum}[page]||home)();
})();
